<?php require_once __DIR__.'/../includes/layout.php';require_once __DIR__.'/../includes/widgets.php';require_once __DIR__.'/../includes/calendar_view.php';$u=require_role('paciente');$up=all('SELECT c.*,u.nombre,u.apellido_paterno,m.verificado,e.nombre AS especialidad FROM citas c JOIN medicos m ON m.id=c.medico_id JOIN usuarios u ON u.id=m.usuario_id LEFT JOIN especialidades e ON e.id=m.especialidad_id WHERE c.paciente_id=(SELECT id FROM pacientes WHERE usuario_id=?) AND c.fecha>=CURDATE() AND c.estado="programada" ORDER BY c.fecha,c.hora LIMIT 3',[$u['id']]);$n=row('SELECT COUNT(*) total FROM citas WHERE paciente_id=(SELECT id FROM pacientes WHERE usuario_id=?)',[$u['id']]);$activeTurn=row('SELECT t.id,(SELECT COUNT(*) FROM turnos_virtuales x WHERE x.fecha=t.fecha AND x.estado="en_espera" AND x.id<=t.id) posicion FROM turnos_virtuales t WHERE t.paciente_id=(SELECT id FROM pacientes WHERE usuario_id=?) AND t.fecha=CURDATE() AND t.estado="en_espera" ORDER BY t.id DESC LIMIT 1',[$u['id']]);header_ui('¡Hola, '. $u['nombre'].'! 👋');?><section class="welcome-banner"><div><span class="pill pill-light">✦ BIENVENIDO A TU ESPACIO</span><h2>Tu salud es nuestra prioridad.</h2><p>Agenda una consulta y empieza a cuidar de ti, un día a la vez.</p><a class="btn btn-white" href="<?=url('paciente/agendar.php')?>">+ Agendar una cita →</a></div><div class="banner-heart">♥</div></section><div class="stat-grid"><?php stat_card('▦','Citas registradas',$n['total']??0);stat_card('◷','Próximas consultas',count($up),'lavender');stat_card('♥','Tu espacio','MiSalud','peach');?></div><?php if($activeTurn):?><div class="patient-turn-reminder"><div><span>🎟️ TU TURNO VIRTUAL DE HOY</span><strong>#<?=str_pad($activeTurn['id'],4,'0',STR_PAD_LEFT)?> · Posición <?= (int)$activeTurn['posicion']?></strong><small>Consulta tu avance cuando lo necesites.</small></div><a class="btn btn-white btn-sm" href="<?=url('paciente/mi_turno.php')?>">Consultar turno →</a></div><?php endif;?><?php calendar_view('paciente'); ?><div class="dashboard-grid"><section class="panel"><div class="panel-heading"><h2>Mis próximas citas</h2><a href="<?=url('paciente/mis_citas.php')?>">Ver todas →</a></div><?php if(!$up):empty_state('Sin citas próximas','Tu próxima cita puede comenzar hoy.','paciente/agendar.php','Agendar ahora');else:foreach($up as $c):?><div class="appointment-row"><div class="date-square"><strong><?=date('d',strtotime($c['fecha']))?></strong><span><?=date('M',strtotime($c['fecha']))?></span></div><div class="appointment-info"><strong>Dr(a). <?=e($c['nombre'].' '.$c['apellido_paterno'])?></strong><small><?=e($c['especialidad']??'Medicina general')?> · <?=ui_time($c['hora'])?></small></div><span class="badge badge-mint">Confirmada</span></div><?php endforeach;endif;?></section><section class="panel quick-panel"><div class="panel-heading"><h2>Accesos rápidos</h2></div><a href="<?=url('paciente/agendar.php')?>"><span>🗓</span> Nueva cita <b>→</b></a><a href="<?=url('paciente/mi_turno.php')?>"><span>🎟</span> Mi turno virtual <b>→</b></a><a href="<?=url('paciente/donaciones.php')?>"><span>💗</span> Donaciones <b>→</b></a><a href="<?=url('paciente/perfil.php')?>"><span>⚙</span> Mi perfil <b>→</b></a></section></div><?php footer_ui();?>
